let _bulkSelected=new Set();
let _bulkMode=false;
function toggleBulkMode(){
  _bulkMode=!_bulkMode;
  _bulkSelected.clear();
  renderCurrentTaskView();
  const bar=$('bulk-action-bar');
  if(bar)bar.style.display=_bulkMode?'flex':'none';
}
function toggleBulkSelect(id,ev){
  ev.stopPropagation();
  if(_bulkSelected.has(id))_bulkSelected.delete(id);
  else _bulkSelected.add(id);
  const bar=$('bulk-action-bar');
  if(bar){const n=_bulkSelected.size;bar.querySelector('#bulk-count').textContent=n+' selected';}
  const row=document.querySelector(`[data-task-id="${id}"]`);
  if(row)row.style.background=_bulkSelected.has(id)?'var(--acs)':'';
}
function bulkAction(action){
  if(!_bulkSelected.size){toast('No tasks selected');return;}
  const ids=[..._bulkSelected];
  if(action==='done'){
    if(!confirm(`Mark ${ids.length} task(s) as Done?`))return;
    const affectedGoalIds=new Set();
    ids.forEach(id=>{
      const t=D.tasks.find(x=>x.id===id);
      if(t){
        t.status='Done';
        _syncTaskCompletedAt(t);
        maybeSpawnRecurring(t);
        D.goals.forEach(g=>{if((g.linkedTaskIds||[]).includes(t.id))affectedGoalIds.add(g.id);});
        if(t.linkedGoalId)affectedGoalIds.add(t.linkedGoalId);
      }
    });
    save('tasks');
    affectedGoalIds.forEach(gid=>{const g=D.goals.find(x=>x.id===gid);if(g)autoCalcGoalPctBidirectional(g);});
    toast(`✓ ${ids.length} task(s) marked Done`);
  } else if(action==='delete'){
    if(!confirm(`Delete ${ids.length} task(s)? This cannot be undone.`))return;
    D.tasks=D.tasks.filter(t=>!ids.includes(t.id));
    save('tasks');toast(`🗑 ${ids.length} task(s) deleted`);
  } else if(action==='project'){
    const pName=prompt('Move to project (enter project name):');
    if(!pName)return;
    const p=D.projects.find(x=>x.name.toLowerCase()===pName.toLowerCase());
    if(!p){toast('Project not found');return;}
    ids.forEach(id=>{const t=D.tasks.find(x=>x.id===id);if(t){t.projectId=p.id;t.project=p.name;}});
    save('tasks');toast(`📁 ${ids.length} task(s) moved to ${p.name}`);
  } else if(action==='someday'){
    ids.forEach(id=>{const t=D.tasks.find(x=>x.id===id);if(t)t.status='Someday';});
    save('tasks');toast(`💤 ${ids.length} task(s) moved to Someday`);
  }
  _bulkSelected.clear();
  updateSidebarBadges();
  renderCurrentTaskView();
}
// ====== RECURRENCE RULE HELPERS ======
// The drawer keeps the existing "None / Daily / Weekly / Bi-weekly / Monthly /
// Yearly" dropdown that long-term users know, then mirrors the choice into a
// structured `recurrenceRule` JSON object the server-side cron consumes to
// materialize future instances. The "⚙ Advanced" expander lets a user pick
// specific weekdays (for weekly rules), an "until" date, or a max count
// — anything the simple dropdown can't express.
function _parseRecurrenceRule(raw){
  if(!raw)return {};
  try{const r=typeof raw==='string'?JSON.parse(raw):raw;return r&&typeof r==='object'?r:{};}catch{return {};}
}
function _toggleRecurrenceAdvanced(){
  const el=document.getElementById('dr-recurring-adv');
  if(!el)return;
  el.style.display=el.style.display==='none'?'block':'none';
}
function _onRecurringChange(){
  // Reveal byDay row only when relevant.
  const sel=document.getElementById('dr-recurring');
  const byDay=document.getElementById('dr-rec-byday');
  if(!sel||!byDay)return;
  byDay.style.display=(sel.value==='Weekly'||sel.value==='Bi-weekly')?'block':'none';
}
function _buildRecurrenceRuleFromDrawer(){
  const sel=document.getElementById('dr-recurring');
  if(!sel)return null;
  const v=sel.value;
  if(!v||v==='None')return null;
  const freqMap={Daily:'daily',Weekly:'weekly','Bi-weekly':'weekly',Monthly:'monthly',Yearly:'yearly'};
  const freq=freqMap[v];
  if(!freq)return null;
  const intervalEl=document.getElementById('dr-rec-interval');
  let interval=parseInt(intervalEl?intervalEl.value:'',10);
  if(!Number.isFinite(interval)||interval<1)interval=1;
  if(v==='Bi-weekly')interval=Math.max(interval,2);
  const rule={freq,interval};
  if(freq==='weekly'){
    const days=Array.from(document.querySelectorAll('[data-rec-day]')).filter(el=>el.checked).map(el=>Number(el.getAttribute('data-rec-day')));
    if(days.length)rule.byDay=days;
  }
  const untilEl=document.getElementById('dr-rec-until');
  if(untilEl&&untilEl.value)rule.until=untilEl.value;
  const countEl=document.getElementById('dr-rec-count');
  const count=countEl?parseInt(countEl.value,10):NaN;
  if(Number.isFinite(count)&&count>0)rule.count=count;
  return JSON.stringify(rule);
}
// ====== TASK TIME TRACKER ======
// Local-first: t.timeSpent stays as the in-memory counter so the timer feels
// instant and survives offline. The server endpoints (timeEntries.start /
// .stop) fire-and-forget so the time_entries table accrues a real audit log
// that survives device wipes and powers cross-device totals. If the server
// call fails the local counter is still correct.
let _timerTaskId=null,_timerStart=null,_timerInterval=null;
function startTaskTimer(id,event){
  if(event)event.stopPropagation();
  if(_timerTaskId===id){stopTaskTimer();return;}
  if(_timerTaskId)stopTaskTimer();
  _timerTaskId=id;
  _timerStart=Date.now();
  _timerInterval=setInterval(()=>{
    const el=document.getElementById('timer-display-'+id);
    if(el){
      const secs=Math.floor((Date.now()-_timerStart)/1000);
      const h=Math.floor(secs/3600),m=Math.floor((secs%3600)/60),s=secs%60;
      el.textContent=(h?h+'h ':'')+m+'m '+s+'s';
    }
  },1000);
  // Update button appearance
  const btn=document.getElementById('timer-btn-'+id);
  if(btn){btn.style.background='var(--red)';btn.style.color='#fff';btn.title='Stop timer';}
  toast('▶ Timer started for task');
  // Fire-and-forget server start. Server-side single-active-timer enforcement
  // means an in-flight previous run gets auto-stopped too — matches the
  // existing local "stop any running timer first" behaviour.
  if(typeof _trpc==='function'){
    _trpc('timeEntries.start',{taskId:String(id),source:'local'},'mutation').catch(()=>{});
  }
}
function stopTaskTimer(){
  if(!_timerTaskId)return;
  const stoppedId=_timerTaskId;
  const elapsed=Math.round((Date.now()-_timerStart)/60000); // minutes
  const t=D.tasks.find(x=>x.id===stoppedId);
  if(t&&elapsed>0){
    t.timeSpent=(t.timeSpent||0)+elapsed;
    save('tasks');
    toast(`⏹ Timer stopped: +${elapsed} min logged (total: ${t.timeSpent} min)`);
  }
  clearInterval(_timerInterval);
  _timerTaskId=null;_timerStart=null;_timerInterval=null;
  renderCurrentTaskView();
  if(typeof _trpc==='function'){
    _trpc('timeEntries.stop',{taskId:String(stoppedId)},'mutation').catch(()=>{});
  }
}
// Drawer "Estimated 90m / Actual 67m" line. Reads from the server
// time_entries table so it survives device wipes. Falls back to the local
// t.timeSpent counter when offline.
async function _hydrateTaskActuals(t){
  const lineEl=document.getElementById('dr-actual-line');
  if(!lineEl)return;
  const fmt=mins=>{
    if(!mins)return '0m';
    const h=Math.floor(mins/60);const m=mins%60;
    return (h?h+'h ':'')+(m?m+'m':(h?'':'0m'));
  };
  const est=t.estimatedMins||0;
  // Local fallback first so something shows immediately.
  if(t.timeSpent){
    lineEl.textContent=`· Actual ${fmt(t.timeSpent)}`;
    lineEl.style.color=est&&t.timeSpent>est?'var(--red)':'var(--ok)';
  }
  try{
    const totals=await _trpc('timeEntries.totalsByTask',{},'query');
    const row=Array.isArray(totals)?totals.find(r=>String(r.taskId)===String(t.id)):null;
    const actualMins=row?Number(row.mins)||0:0;
    if(actualMins){
      const variance=est?Math.round((actualMins-est)/est*100):0;
      const varianceLabel=est?` (${variance>=0?'+':''}${variance}%)`:'';
      lineEl.textContent=`· Actual ${fmt(actualMins)}${varianceLabel}`;
      lineEl.style.color=est&&actualMins>est?'var(--red)':(est?'var(--ok)':'var(--t3)');
    }
  }catch{ /* offline — leave local fallback if any */ }
}

// Recover from a page reload mid-timer: ask the server whether a timer is
// running for the current user and resume the in-page counter from its start.
// Idempotent — safe to call on every boot.
async function _restoreRunningTimer(){
  try{
    const running=await _trpc('timeEntries.running',undefined,'query');
    if(!running)return;
    const numericId=Number(running.taskId);
    if(!Number.isFinite(numericId))return; // external-task timer, no local row to attach to
    if(_timerTaskId)return; // already running locally
    const startMs=new Date(running.startedAt).getTime();
    _timerTaskId=numericId;
    _timerStart=startMs;
    _timerInterval=setInterval(()=>{
      const el=document.getElementById('timer-display-'+numericId);
      if(el){
        const secs=Math.floor((Date.now()-_timerStart)/1000);
        const h=Math.floor(secs/3600),m=Math.floor((secs%3600)/60),s=secs%60;
        el.textContent=(h?h+'h ':'')+m+'m '+s+'s';
      }
    },1000);
  }catch{ /* offline / not signed in — fine */ }
}
function taskRow(t,showActs=true){
  const isSomeday=t.status==='Someday';
  const _todayForRow=(new Date()).toISOString().split('T')[0];
  const isOverdueTask=t.status!=='Done'&&t.due&&t.due<_todayForRow;
  const assigneeLabel=t.assignedTo?`👤 ${t.assignedTo.split(' ')[0]}`:'Delegate';
  const bulkChk=_bulkMode?`<div class="chk ${_bulkSelected.has(t.id)?'on':''}" style="flex-shrink:0;margin-right:2px" onclick="toggleBulkSelect(${t.id},event)"></div>`:
    `<div class="chk ${t.status==='Done'?'on':''}" onclick="event.stopPropagation();toggleTask(${t.id})"></div>`;
  // Blocked indicator: task is blocked if any predecessor task is not Done
  const isBlocked=(t.predecessorIds||[]).length>0&&(t.predecessorIds||[]).some(pid=>{
    const pred=D.tasks.find(x=>x.id===pid);
    return pred&&pred.status!=='Done';
  });
  const blockedLabel=isBlocked?`<span style="font-size:11px;color:var(--red);white-space:nowrap;font-weight:600" title="Blocked by incomplete predecessor tasks">🔒 Blocked</span>`:'';
  const isTimerActive=_timerTaskId===t.id;
  const timerBtn=`<button id="timer-btn-${t.id}" class="btn btn-s" style="height:20px;font-size:10px;padding:0 5px;${isTimerActive?'background:var(--red);color:#fff':''}" title="${isTimerActive?'Stop timer':'Start timer'}" onclick="event.stopPropagation();startTaskTimer(${t.id},event)">${isTimerActive?'⏹':'▶'}</button>`;
  const timeLabel=t.timeSpent?`<span style="font-size:11px;color:var(--t3);white-space:nowrap" title="Time spent">${t.timeSpent}m</span>`:
    (isTimerActive?`<span id="timer-display-${t.id}" style="font-size:11px;color:var(--red);white-space:nowrap;font-variant-numeric:tabular-nums">0m 0s</span>`:'');
  const blockBtn=`<button class="btn btn-s" style="height:20px;font-size:10px;padding:0 5px" title="Block time in Calendar" onclick="event.stopPropagation();blockTaskTime(${t.id})">📅</button>`;
  const _tcStyle=t.titleColor?`color:${t.titleColor};font-weight:600`:'';
  // K: subtask progress chip
  const _subs=Array.isArray(t.subtasks)?t.subtasks:[];
  const _subDone=_subs.filter(s=>s.done).length;
  const _subChip=_subs.length?`<span class="lu-subtask-chip ${_subDone===_subs.length?'done':''}" title="${_subDone} of ${_subs.length} subtask${_subs.length===1?'':'s'} done">☑ ${_subDone}/${_subs.length}</span>`:'';
  // E: clickable priority + status pills with inline picker
  const priPillClickable=`<span class="pill ${pillClass(t.priority)} lu-pill-clickable" title="Click to change priority" onclick="event.stopPropagation();_taskPillPicker(event,${t.id},'priority')">${t.priority}</span>`;
  return `<div class="lr ${isOverdueTask?'lr-overdue':''}" data-task-id="${t.id}" style="${_bulkSelected.has(t.id)?'background:var(--acs)':isOverdueTask?'border-left:2px solid var(--red)':isBlocked?'border-left:2px solid var(--red)':''}" onclick="${_bulkMode?`toggleBulkSelect(${t.id},event)`:`openDrawer('task',D.tasks.find(x=>x.id===${t.id}))`}">${bulkChk}<span class="rt" style="${_tcStyle}">${esc(t.title)}</span>${_subChip}${isOverdueTask?`<span style="font-size:11px;color:var(--red);white-space:nowrap;font-weight:600">⚠ Overdue</span>`:''} ${blockedLabel}${priPillClickable}<span class="rm" style="${isOverdueTask?'color:var(--red);font-weight:600':''}">${t.due?fmtDate(t.due):''}</span>${t.assignedTo?`<span style="font-size:11px;color:var(--t3);white-space:nowrap">${esc(t.assignedTo.split(' ')[0])}</span>`:''} ${timeLabel}${showActs?`<span class="acts">${timerBtn}<button class="btn btn-s" style="height:20px;font-size:10px;padding:0 5px" title="Snooze…" onclick="event.stopPropagation();_taskSnoozePopover(event,${t.id})">⏰</button><button class="lr-row-acts-toggle" title="More actions" onclick="event.stopPropagation();_taskRowMoreToggle(event,${t.id})">⋮</button><div class="lr-row-acts-pop" id="lr-row-acts-${t.id}">${blockBtn ? `<button onclick="event.stopPropagation();_closeAllRowActs();blockTaskTime(${t.id})">${_icon('calendar',12,'currentColor')} Block time in Calendar</button>`:''}<button onclick="event.stopPropagation();_closeAllRowActs();delegateTask(${t.id})">📤 Delegate</button><button onclick="event.stopPropagation();_closeAllRowActs();aiSuggestDelegate(${t.id})">🤖 AI suggest delegate</button>${t.blockedBy?`<button onclick="event.stopPropagation();_closeAllRowActs();aiUnblockTask(${t.id})">🔓 AI unblock</button>`:''}<button onclick="event.stopPropagation();_closeAllRowActs();moveSomeday(${t.id})">${isSomeday?'📥 Move to Inbox':'💤 Move to Someday'}</button><button onclick="event.stopPropagation();_closeAllRowActs();openDrawer('task',D.tasks.find(x=>x.id===${t.id}))">✏ Full edit</button><button onclick="event.stopPropagation();_closeAllRowActs();deleteItem('task',${t.id})" style="color:var(--red)">✕ Delete</button></div></span>`:''}</div>`;
}
function addTaskComment(taskId){
  const inp=document.getElementById('new-comment');
  if(!inp||!inp.value.trim())return;
  const t=D.tasks.find(x=>x.id===taskId);
  if(!t)return;
  t.comments=t.comments||[];
  const now=new Date();
  const ts=now.toLocaleDateString('en-US',{month:'short',day:'numeric'})+' '+now.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'});
  t.comments.push({id:Date.now(),author:D.creds.userName||(D.teams[0]&&D.teams[0].members[0]&&D.teams[0].members[0].name)||'Idris',text:inp.value.trim(),ts});
  save('tasks');
  inp.value='';
  // Re-render comments panel inline
  const panel=document.getElementById('task-comments');
  if(panel)panel.innerHTML=(function(comments){if(!comments||!comments.length)return "<div style='font-size:10px;color:var(--t3);padding:4px 0'>No comments yet.</div>";return comments.map((c,ci)=>{const isOwn=c.author===(D.creds.userName||(D.teams[0]&&D.teams[0].members[0]&&D.teams[0].members[0].name)||'Idris');return `<div style="padding:5px 0;border-bottom:1px solid var(--s3)"><div style="display:flex;justify-content:space-between;align-items:center;font-size:11px;color:var(--t3);margin-bottom:2px"><span>${esc(c.author||'Idris')}</span><div style="display:flex;gap:4px;align-items:center"><span>${c.ts||''}</span>${isOwn?`<span onclick="editTaskComment(${taskId},${ci})" style="cursor:pointer;color:var(--ac);font-size:11px" title="Edit">✏</span><span onclick="deleteTaskComment(${taskId},${ci})" style="cursor:pointer;color:var(--red);font-size:11px" title="Delete">✕</span>`:''}</div></div><div style="font-size:11px">${esc(c.text)}</div></div>`;}).join('');})(t.comments);
  toast('💬 Comment added');
}
function editTaskComment(taskId,ci){
  const t=D.tasks.find(x=>x.id===taskId);
  if(!t||!t.comments[ci])return;
  const newText=prompt('Edit comment:',t.comments[ci].text);
  if(newText===null)return;
  if(!newText.trim()){toast('Comment cannot be empty');return;}
  t.comments[ci].text=newText.trim();
  t.comments[ci].edited=true;
  save('tasks');
  const panel=document.getElementById('task-comments');
  if(panel){
    const comments=t.comments;
    panel.innerHTML=(function(comments){
      if(!comments||!comments.length)return "<div style='font-size:10px;color:var(--t3);padding:4px 0'>No comments yet.</div>";
      return comments.map((c,ci)=>{
        const isOwn=c.author===(D.creds.userName||(D.teams[0]&&D.teams[0].members[0]&&D.teams[0].members[0].name)||'Idris');
        return `<div style="padding:5px 0;border-bottom:1px solid var(--s3)">`
          +`<div style="display:flex;justify-content:space-between;align-items:center;font-size:11px;color:var(--t3);margin-bottom:2px">`
          +`<span>${esc(c.author||'Idris')}</span>`
          +`<div style="display:flex;gap:4px;align-items:center">`
          +`<span>${c.ts||''}${c.edited?' (edited)':''}</span>`
          +(isOwn?`<span onclick="editTaskComment(${taskId},${ci})" style="cursor:pointer;color:var(--ac);font-size:11px" title="Edit">✏</span>`
          +`<span onclick="deleteTaskComment(${taskId},${ci})" style="cursor:pointer;color:var(--red);font-size:11px" title="Delete">✕</span>`:'')
          +`</div></div>`
          +`<div style="font-size:11px">${esc(c.text)}</div>`
          +`</div>`;
      }).join('');
    })(comments);
  }
  toast('✏ Comment updated');
}
function deleteTaskComment(taskId,ci){
  if(!confirm('Delete this comment?'))return;
  const t=D.tasks.find(x=>x.id===taskId);
  if(!t||!t.comments)return;
  t.comments.splice(ci,1);
  save('tasks');
  const panel=document.getElementById('task-comments');
  if(panel){
    panel.innerHTML=t.comments.length
      ?t.comments.map((c,ci)=>{
        const isOwn=c.author===(D.creds.userName||(D.teams[0]&&D.teams[0].members[0]&&D.teams[0].members[0].name)||'Idris');
        return `<div style="padding:5px 0;border-bottom:1px solid var(--s3)">`
          +`<div style="display:flex;justify-content:space-between;align-items:center;font-size:11px;color:var(--t3);margin-bottom:2px">`
          +`<span>${esc(c.author||'Idris')}</span>`
          +`<div style="display:flex;gap:4px;align-items:center">`
          +`<span>${c.ts||''}</span>`
          +(isOwn?`<span onclick="editTaskComment(${taskId},${ci})" style="cursor:pointer;color:var(--ac);font-size:11px" title="Edit">✏</span>`
          +`<span onclick="deleteTaskComment(${taskId},${ci})" style="cursor:pointer;color:var(--red);font-size:11px" title="Delete">✕</span>`:'')
          +`</div></div>`
          +`<div style="font-size:11px">${esc(c.text)}</div>`
          +`</div>`;
      }).join('')
      :"<div style='font-size:10px;color:var(--t3);padding:4px 0'>No comments yet.</div>";
  }
  toast('🗑 Comment deleted');
}
function delegateTask(id){
  const t=D.tasks.find(x=>x.id===id);
  if(!t)return;
  const members=D.teams.flatMap(tm=>tm.members).filter(m=>m.name!==(D.creds.userName||'Idris Grant'));
  if(!members.length){toast('No other team members to delegate to');return;}
  const opts=members.map((m,i)=>`${i+1}. ${m.name} (${m.role})`).join('\n');
  const choice=prompt(`Delegate "${t.title}" to:\n${opts}\n\nEnter number:`);
  if(!choice)return;
  const idx=parseInt(choice)-1;
  if(isNaN(idx)||idx<0||idx>=members.length){toast('Invalid selection');return;}
  const assignee=members[idx].name;
  t.assignedTo=assignee;
  t.status=t.status==='Not Started'?'Delegated':t.status;
  t.comments=t.comments||[];
  const ts=new Date().toLocaleString();
  t.comments.push({id:Date.now(),author:D.creds.userName||'Idris Grant',ts,text:`Delegated to ${assignee}`,type:'delegation'});
  save('tasks');
  toast(`📤 Task delegated to ${assignee}`);
  renderScreen(curScreen);
}
// ====== TASKS AI ======
function aiDecomposeGoal(){
  const goal=prompt('Enter a goal or project to decompose into tasks:');
  if(!goal||!goal.trim())return;
  toast('🧩 Decomposing goal into tasks...');
  // Generate subtasks based on the goal using heuristic decomposition
  const g=goal.trim();
  const verbs=['Research','Draft','Review','Finalize','Schedule','Send','Create','Set up','Test','Present','Coordinate','Document','Implement','Analyze','Design'];
  const count=5+Math.floor(Math.random()*4);
  const subtasks=[];
  const phases=['Planning','Execution','Review'];
  // Build contextual subtasks based on keywords in the goal
  const lower=g.toLowerCase();
  if(lower.includes('launch')||lower.includes('ship')||lower.includes('release')){
    subtasks.push('Define launch criteria and success metrics','Prepare launch checklist','Draft announcement copy','Set up monitoring and alerts','Coordinate with stakeholders','Run final QA pass','Schedule launch date','Prepare rollback plan');
  } else if(lower.includes('report')||lower.includes('analysis')||lower.includes('research')){
    subtasks.push('Define scope and key questions','Gather data sources','Conduct primary research','Analyze findings','Draft executive summary','Create supporting visuals','Review with stakeholders','Finalize and distribute');
  } else if(lower.includes('meeting')||lower.includes('workshop')||lower.includes('session')){
    subtasks.push('Define agenda and objectives','Send calendar invites','Prepare materials and slides','Share pre-read with attendees','Facilitate the session','Capture action items','Send follow-up summary','Track action item completion');
  } else {
    verbs.slice(0,count).forEach((v,i)=>{
      subtasks.push(v+' '+g.split(' ').slice(0,3).join(' ')+(i<3?' — Phase '+(i+1):''));
    });
  }
  const today=new Date();
  const dueDate=new Date(today.getTime()+7*24*60*60*1000).toISOString().slice(0,10);
  const m=document.getElementById('modal-content');
  m.innerHTML=`<h2 style="font-size:15px;font-weight:600;margin-bottom:8px">🧩 AI Task Decomposition</h2>
  <div style="font-size:11px;color:var(--t2);margin-bottom:10px">Goal: <strong>${esc(g)}</strong></div>
  <div style="font-size:11px;color:var(--t3);margin-bottom:8px">Select tasks to add (all selected by default):</div>
  <div id="decomp-list" style="max-height:260px;overflow-y:auto">${subtasks.slice(0,8).map((s,i)=>`<label style="display:flex;align-items:center;gap:8px;padding:5px 0;cursor:pointer;font-size:12px"><input type="checkbox" checked data-idx="${i}" style="accent-color:var(--ac)"> ${esc(s)}</label>`).join('')}</div>
  <div style="display:flex;gap:8px;margin-top:12px">
  <button class="btn btn-p" onclick="(function(){
    const checks=document.querySelectorAll('#decomp-list input:checked');
    if(!checks.length){toast('Select at least one task');return;}
    const titles=[...checks].map(c=>c.closest('label').textContent.trim());
    titles.forEach(title=>{
      D.tasks.push({id:Date.now()+Math.random(),title,priority:'Medium',due:'${dueDate}',status:'Not Started',context:'Deep Work',project:'',tags:['ai-generated'],notes:'Generated from goal: ${esc(g)}',myDay:false,energy:'medium',subtasks:[],comments:[],createdBy:D.creds.userName||'Idris Grant'});
    });
    save('tasks');renderScreen('tasks');closeModal();
    toast('✓ '+titles.length+' tasks added!');
  })()">✓ Add Selected Tasks</button>
  <button class="btn btn-s" onclick="closeModal()">Cancel</button>
  </div>`;
  document.getElementById('modal-capture').classList.add('show');
}

function aiDeadlineRisk(){
  toast('⚠️ Analyzing deadline risk...');
  const today=new Date();
  const risks=[];
  D.tasks.filter(t=>t.status!=='Done'&&t.due).forEach(t=>{
    const due=new Date(t.due);
    const daysLeft=Math.ceil((due-today)/(1000*60*60*24));
    const subtasksDone=(t.subtasks||[]).filter(s=>s.done).length;
    const subtasksTotal=(t.subtasks||[]).length;
    const pct=subtasksTotal>0?subtasksDone/subtasksTotal:0;
    const estMins=t.estimatedMins||60;
    const hoursNeeded=estMins/60;
    let risk='low';
    if(daysLeft<0)risk='overdue';
    else if(daysLeft<=1&&pct<0.5)risk='critical';
    else if(daysLeft<=3&&pct<0.3)risk='high';
    else if(daysLeft<=7&&pct<0.2)risk='medium';
    if(risk!=='low')risks.push({t,daysLeft,pct,risk,hoursNeeded});
  });
  if(!risks.length){toast('✅ No deadline risks detected — you\'re on track!');return;}
  risks.sort((a,b)=>['overdue','critical','high','medium'].indexOf(a.risk)-['overdue','critical','high','medium'].indexOf(b.risk));
  const riskColors={overdue:'var(--red)',critical:'var(--red)',high:'#f97316',medium:'#eab308'};
  const riskLabels={overdue:'🔴 OVERDUE',critical:'🔴 CRITICAL',high:'🟠 HIGH',medium:'🟡 MEDIUM'};
  const m=document.getElementById('modal-content');
  m.innerHTML=`<h2 style="font-size:15px;font-weight:600;margin-bottom:8px">⚠️ Deadline Risk Report</h2>
  <div style="font-size:11px;color:var(--t2);margin-bottom:10px">${risks.length} task${risks.length!==1?'s':''} at risk:</div>
  <div style="max-height:300px;overflow-y:auto">${risks.map(r=>`<div style="padding:8px;margin-bottom:6px;border-radius:6px;border-left:3px solid ${riskColors[r.risk]};background:var(--s2)">
    <div style="display:flex;align-items:center;gap:6px;margin-bottom:3px"><span style="font-size:11px;font-weight:700;color:${riskColors[r.risk]}">${riskLabels[r.risk]}</span><span style="font-size:11px;font-weight:600">${esc(r.t.title)}</span></div>
    <div style="font-size:11px;color:var(--t3)">${r.daysLeft<0?Math.abs(r.daysLeft)+' days overdue':r.daysLeft+' day'+( r.daysLeft!==1?'s':'')+' left'} · ${Math.round(r.pct*100)}% complete · ~${r.hoursNeeded.toFixed(1)}h estimated</div>
  </div>`).join('')}</div>
  <div style="display:flex;gap:8px;margin-top:12px">
  <button class="btn btn-p" onclick="closeModal()">Got it</button>
  </div>`;
  document.getElementById('modal-capture').classList.add('show');
}

function aiAutoPriority(){
  toast('✨ Scoring and re-prioritizing tasks...');
  const today=new Date();
  D.tasks.filter(t=>t.status!=='Done').forEach(t=>{
    const due=new Date(t.due||'2099-12-31');
    const daysLeft=Math.ceil((due-today)/(1000*60*60*24));
    // Urgency: 0-40 pts
    const urgency=daysLeft<=0?40:daysLeft<=1?35:daysLeft<=3?28:daysLeft<=7?20:daysLeft<=14?12:5;
    // Importance: 0-30 pts (based on existing priority + linked goal)
    const impBase={High:30,Medium:20,Low:10}[t.priority]||15;
    const goalBonus=t.linkedGoalId?10:0;
    const importance=Math.min(30,impBase+goalBonus);
    // Energy alignment: 0-15 pts
    const energyScore={high:15,medium:10,low:5}[t.energy]||10;
    // Subtask progress: 0-15 pts
    const subs=t.subtasks||[];
    const progScore=subs.length>0?Math.round((subs.filter(s=>s.done).length/subs.length)*15):0;
    const total=urgency+importance+energyScore+progScore;
    t._aiScore=total;
    // Assign priority based on score
    if(total>=75)t.priority='High';
    else if(total>=45)t.priority='Medium';
    else t.priority='Low';
  });
  D.tasks.sort((a,b)=>(b._aiScore||0)-(a._aiScore||0));
  save('tasks');
  renderCurrentTaskView();
  toast('✨ Tasks re-scored and sorted by AI priority!');
}

// ─── AI Compose for task notes ──────────────────────────────────────────────
// Generates a draft description for a task based on its title, project, tags,
// and existing notes. Targets the dr-notes-rte contenteditable (the Notes
// field is now a Rich Text Editor, not a plain textarea). The preview modal
// detects target type and inserts rendered HTML when targeting an RTE.
async function aiComposeTaskNotes(id){
  const t=D.tasks.find(x=>x.id===id);if(!t)return;
  // Prefer the RTE; fall back to the legacy textarea id for back-compat.
  const target=document.getElementById('dr-notes-rte')||document.getElementById('dr-notes');
  if(!target)return;
  const btn=document.getElementById('btn-dr-task-ai-desc');
  const orig=btn?btn.textContent:'';
  if(btn){btn.textContent='⏳ Composing...';btn.disabled=true;}
  try{
    const projectName=t.project||(t.projectId?(D.projects.find(p=>p.id===t.projectId)||{}).name:'')||'';
    // Pull existing notes as PLAIN TEXT so the AI doesn't see HTML tags.
    // RTE: innerText. Textarea: .value.
    // Cap existing notes so the combined userContent stays under ai.assist's
    // 8000-char zod limit (rich-text task notes can be long).
    const existingText=(target.isContentEditable?(target.innerText||'').trim():(target.value||'').trim()).slice(0,6000);
    const ctxLines=[
      `Title: ${t.title}`,
      projectName?`Project: ${projectName}`:'',
      t.priority?`Priority: ${t.priority}`:'',
      t.due?`Due: ${t.due}`:'',
      (t.tags||[]).length?`Tags: ${(t.tags||[]).join(', ')}`:'',
      existingText?`Existing notes (rewrite/extend):\n${existingText}`:'',
    ].filter(Boolean).join('\n').slice(0,7800);
    const {provider,apiKey}=_getAIConfig();
    const sys='You are a task description writer for a productivity app. Given the task metadata, write a clear description explaining what the task involves, why it matters, and what "done" looks like. Markdown formatting (## headings, **bold**, bullets) is allowed when it genuinely helps clarity.'+(typeof _aiLengthHint==='function'?_aiLengthHint():'');
    const res=await _trpc('ai.assist',{
      systemPrompt:sys,
      userContent:ctxLines,
      provider:provider||'manus',apiKey:apiKey||undefined,
    },'mutation');
    const text=res?.result||res?.text||'';
    if(text){_aiComposePreview('task',id,text.trim(),target.id,'aiComposeTaskNotes');}
    else toast('No description generated');
  }catch(e){toast('AI compose failed: '+(e.message||e));}
  finally{if(btn){btn.textContent=orig||'✨ AI Compose';btn.disabled=false;}}
}

// AI Suggest Subtasks: ask the model to propose 3-6 subtasks for the current
// task. Shows a checkbox modal letting the user pick which to keep.
async function aiSuggestSubtasks(id){
  const t=D.tasks.find(x=>x.id===id);if(!t)return;
  const btn=document.getElementById('btn-dr-task-ai-subs');
  const orig=btn?btn.textContent:'';
  if(btn){btn.textContent='⏳ Thinking...';btn.disabled=true;}
  try{
    const projectName=t.project||(t.projectId?(D.projects.find(p=>p.id===t.projectId)||{}).name:'')||'';
    // Notes are now rich text and can be long — strip HTML and cap so the
    // combined userContent stays under ai.assist's 8000-char zod limit.
    const _plain=s=>String(s||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
    const notesPlain=_plain(t.notes).slice(0,6000);
    const ctxLines=[
      `Task: ${t.title}`,
      projectName?`Project: ${projectName}`:'',
      notesPlain?`Notes:\n${notesPlain}`:'',
      (t.subtasks||[]).length?`Existing subtasks (avoid duplicates):\n- `+(t.subtasks||[]).map(s=>s.title).join('\n- '):'',
    ].filter(Boolean).join('\n').slice(0,7800);
    const {provider,apiKey}=_getAIConfig();
    const res=await _trpc('ai.assist',{
      systemPrompt:'You are a task breakdown assistant. Given a task, propose 3-6 concrete subtasks that, completed in order, would finish it. Return ONLY a JSON object of the form {"subtasks":["First action","Second action",...]} with no extra commentary. Each subtask is a short imperative phrase, max 80 chars.',
      userContent:ctxLines,
      provider:provider||'manus',apiKey:apiKey||undefined,
    },'mutation');
    const text=res?.result||res?.text||'';
    let arr=[];
    try{const parsed=JSON.parse(text.replace(/^```(?:json)?|```$/g,'').trim());arr=Array.isArray(parsed.subtasks)?parsed.subtasks:[];}catch(_){
      // Fallback: parse plain bullet/line list
      arr=text.split('\n').map(l=>l.replace(/^[-*\d.\s]+/,'').trim()).filter(l=>l&&l.length<200);
    }
    arr=arr.slice(0,8);
    if(!arr.length){toast('No subtasks suggested');return;}
    const m=document.getElementById('modal-content');
    m.innerHTML=`<h2 style="font-size:15px;font-weight:600;margin-bottom:8px">🧩 AI Suggested Subtasks</h2>
      <div style="font-size:11px;color:var(--t2);margin-bottom:10px">Task: <strong>${esc(t.title)}</strong></div>
      <div style="font-size:11px;color:var(--t3);margin-bottom:8px">Pick which to add (all selected by default):</div>
      <div id="ai-sub-list" style="max-height:300px;overflow-y:auto">${arr.map((s,i)=>`<label style="display:flex;align-items:flex-start;gap:8px;padding:6px 0;cursor:pointer;font-size:12px;line-height:1.4"><input type="checkbox" checked data-idx="${i}" style="accent-color:var(--ac);margin-top:3px"><span>${esc(s)}</span></label>`).join('')}</div>
      <div style="display:flex;gap:8px;margin-top:12px">
        <button class="btn btn-p" onclick="_applyAISubtasks(${id})">Add Selected</button>
        <button class="btn btn-s" onclick="closeModal()">Cancel</button>
      </div>`;
    window._aiSubtasksList=arr;window._aiSubtasksTaskId=id;
    document.getElementById('modal-capture').classList.add('show');
  }catch(e){toast('AI suggest failed: '+(e.message||e));}
  finally{if(btn){btn.textContent=orig||'🧩 AI Suggest Subtasks';btn.disabled=false;}}
}
function _applyAISubtasks(id){
  const t=D.tasks.find(x=>x.id===id);if(!t)return;
  t.subtasks=t.subtasks||[];
  const arr=window._aiSubtasksList||[];
  const picks=[...document.querySelectorAll('#ai-sub-list input[type=checkbox]')]
    .filter(cb=>cb.checked).map(cb=>arr[Number(cb.dataset.idx)]).filter(Boolean);
  let nextId=t.subtasks.length?Math.max(...t.subtasks.map(s=>s.id||0))+1:1;
  picks.forEach(title=>{t.subtasks.push({id:nextId++,title,done:false});});
  save('tasks');closeModal();
  // Refresh drawer if open. The actual open marker is `.show` on #drawer-ov;
  // the previous `.drawer.open` selector never matched, so the new subtasks
  // didn't appear until the user closed and reopened the task.
  const ov=document.getElementById('drawer-ov');
  if(ov&&ov.classList.contains('show')&&typeof openDrawer==='function')openDrawer('task',t);
  toast('✓ Added '+picks.length+' subtask'+(picks.length===1?'':'s'));
}

